-- Built In rotation text: each key is the rotation ID plus .Name or .Description.
if GetLocale() ~= "frFR" then return end
local addon_name = ...
local host = RotationMasterBuiltIns
local L = LibStub("AceLocale-3.0"):GetLocale(host and host.localeName or addon_name:match("^(.-)_[^_]+$") or addon_name)

L["rm.retail.evoker.augmentation.Name"] = "Icy Veins"
L["rm.retail.evoker.augmentation.Description"] = "Recommandée pour Augmentation : la priorité Puissance d’ébène d'Icy Veins. Puissance d’ébène est l'une des rares améliorations que le jeu montre encore aux addons en combat dans Midnight : son entretien y fonctionne donc. Hors combat : Écailles torrides sur une cible amicale du groupe qui ne l'a pas, Flamme vivante sur un ennemi. Puis Puissance d’ébène quand elle manque ou sous 4 secondes, et dès qu'elle est prête sauf si Souffle des présages est prêt ; Prescience ; Souffle de feu ; Soulèvement ; Éruption pendant Puissance d’ébène ou avec deux cumuls d'Explosion d’essence ; Frappe d’azur ; Flamme vivante. En combat, une amélioration masquée ne fait sauter que sa propre étape. Rappels : Souffle des présages et Souffle profond (vous les visez), Retour de bâton avec Souffle de feu prêt, Bond temporel quand Souffle de feu et Soulèvement sont tous deux en recharge, plus les rappels utilitaires. Prescience et Écailles torrides se lancent sur votre cible : le choix de l'allié, et le rang de renforcement, vous reviennent."
L["rm.retail.evoker.augmentation.assisted.Name"] = "Assistant de combat Blizzard"
L["rm.retail.evoker.augmentation.assisted.Description"] = "La suggestion de l'Assistant de combat de Blizzard pour Augmentation, une alternative à la rotation intégrée Augmentation d'Icy Veins recommandée, désactivée par défaut : activez-la et désactivez l'autre, ou augmentez sa priorité. Elle ne relance Puissance d’ébène qu'après son expiration, et attend pendant que vous incantez ou maintenez un sort renforcé. Rappels en combat pour Souffle des présages, Souffle profond, Retour de bâton et Bond temporel, plus Apaisement, Écailles d’obsidienne, Bénédiction du bronze et Source de magie comme dans les autres rotations intégrées Évocateur."
L["rm.retail.evoker.devastation.Name"] = "Assistant de combat Blizzard"
L["rm.retail.evoker.devastation.Description"] = "Recommandée pour Dévastation. Met en surbrillance le prochain sort suggéré par l'Assistant de combat de Blizzard, le seul conseil de rotation que le jeu laisse encore lire à un addon en combat dans Midnight ; elle attend pendant que vous incantez, canalisez Désintégration ou maintenez un sort renforcé. Le choix du rang de renforcement vous revient. En complément, des rappels en combat pour Rage draconique, Souffle profond et Retour de bâton, Apaisement sur une incantation interruptible et Écailles d’obsidienne dès qu'elles sont prêtes, et hors combat Bénédiction du bronze quand elle manque et Source de magie sur une cible amicale de votre groupe. Les incantations ennemies sont masquées en combat, donc Apaisement ne s'allume que là où le jeu les affiche ; la vie est masquée sur Retail, donc le moment d'utiliser Écailles d’obsidienne est à votre appréciation."
L["rm.retail.evoker.devastation.guide.Name"] = "Référence (SimulationCraft et Icy Veins)"
L["rm.retail.evoker.devastation.guide.Description"] = "Référence uniquement, désactivée par défaut : la priorité Dévastation optimale. Les procs, les temps de recharge et la brûlure sur la cible sont masqués en combat dans Midnight ; elle ne peut donc pas s'y exécuter : lisez-la, ou dupliquez-la pour expérimenter. Engage avec Flamme vivante. Squammandant (Désintégration de masse connue) : Afflux d’éternité, Souffle de feu, Souffle profond face à deux ennemis ou plus, Désintégration avec des charges de Désintégration de masse, Bûcher face à cinq ennemis ou plus, Désintégration, Flamme vivante sur Incandescence avec Flammes bondissantes, Flamme déchaînée sous deux cumuls d'Explosion d’essence, Balayage d’azur. Sculpte-flammes : Afflux d’éternité, Souffle de feu quand sa brûlure manque ou se termine, Bûcher face à cinq ennemis ou plus, Désintégration, Souffle profond face à quatre ou plus, Flamme déchaînée, Flamme vivante sur Incandescence avec Flammes bondissantes, Balayage d’azur. Puis Frappe d’azur en mouvement, Flamme vivante, Frappe d’azur. Utilisez les sorts renforcés au rang 1 contre une seule cible (Icy Veins). Rappels : Rage draconique, Retour de bâton pendant Rage draconique ou avec Souffle de feu prêt, Souffle profond en Squammandant, plus les rappels utilitaires."
L["rm.retail.evoker.initial.Name"] = "Assistant de combat Blizzard"
L["rm.retail.evoker.initial.Description"] = "Recommandée avant de choisir une spécialisation (tant que le jeu signale la spécialisation initiale de l'Évocateur). Met en surbrillance le prochain sort suggéré par l'Assistant de combat de Blizzard, le seul conseil de rotation que le jeu laisse encore lire à un addon en combat dans Midnight ; elle attend pendant que vous incantez ou canalisez. En complément, les rappels que partagent toutes les rotations intégrées de l'Évocateur, chacun dès que vous connaissez son sort. Lorsque vous choisissez une spécialisation au niveau 10, les rotations intégrées de cette spécialisation prennent le relais."
L["rm.retail.evoker.preservation.Name"] = "Référence (Icy Veins)"
L["rm.retail.evoker.preservation.Description"] = "Référence uniquement, désactivée par défaut. La vie des alliés, Écho, Réversion, Explosion d’essence et chaque temps de recharge sont masqués aux addons en combat dans Midnight, Rotation Master ne peut pas choisir qui soigner, et Blizzard n'a aucune rotation d'Assistant de combat pour les soigneurs : cette rotation intégrée ne soigne donc pas. Elle vous rappelle Bénédiction du bronze et Source de magie hors combat, et quand votre cible est un ennemi, elle suggère des dégâts : Souffle de feu, Désintégration, Flamme vivante, et Frappe d’azur en mouvement. Rappels d'Apaisement et d'Écailles d’obsidienne comme dans les autres rotations intégrées Évocateur. Les soins restent à votre charge."
